from scipy.optimize import least_squares
def mk(gfun):
    def resid(p):
        g=gfun(p)
        X=np.column_stack([np.ones_like(P)*0+g*1, g*P, g*P**2, g*P**3, np.ones_like(P), P, P**2])
        # linear in coefficients
        c=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
        return X@c-dP_dt
    return resid
